#!/bin/bash
# 场景图 v3：按《场景质量标准 v1》（11-02 13:33）。13:39 测 H1；13:43 Rhett「按新标准把一组都生成出来」批准全组。
cd /workspace/work/.agents/skills/credit-media-skill
export CREDIT_MEDIA_API_KEY=proxy
O=/workspace/projects/04b4b2af-0042-4c1b-a4f3-cdc315529fa5/promo/scenes_v3; KV=$O/../keyvisual_v1
PRE="写实电影级场景概念图，16:9宽银幕横构图，与参考图同一质感「暗岩传说」，供游戏开发按图搭建场景：结构清楚、可读。无人物或只有极小人物剪影提供尺度。"
STD="【光影】主光、补光、关键点光逻辑清楚，冷暖对比明确；【雾】分层体积雾，近处淡、远处浓，雾色随区域调色，不要全局一层灰雾；【材质】高清真实PBR质感：湿石有高光反光、干土哑光、铜器有铜绿锈、石缝有苔藓、潮痕与水渍、裂纹，墙角石缝与物件接地处有明显接触暗角，物件不能浮在地面上；【布景】近景/中景/远景层次分明：前景地表碎件与叙事小道具，中景小礁与灌木，远景大件地标，边缘自然过渡，不留大片空地；【水面】有清晰倒影。"
NEG="画面中不要出现任何文字、字幕、水印、UI；不要卡通；不要过度锐化或塑料感。"
gen(){ n=$1; p=$2; shift 2; a=(); for i in "$@"; do a+=(--image "$i"); done
  bash scripts/run.sh image --model gpt-image-2 --size 1536x1024 --quality high --prompt "$PRE $p $STD $NEG" "${a[@]}" --out $O/$n.png > $O/$n.log 2>&1 & }
gen H2_forge_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。铸造台（铸钟坊内部），平视略俯。【主色调】熔铜橙金为主，阴影青绿。【光源】主光=中央铸造砧台下熔炉的橙金上照光；补光=右侧高窗透进的冷青光，窗外可见倒挂城市的冷青灯点；关键点光=砧台一圈发光符文、坩埚口、墙上小火盆。【雾】近处热浪与火星，中景淡橙烟，远处高梁下浓灰青烟。【地标】中央带发光符文圈的铸造砧台；左后方墙上一道向下的铜梯拱门，门楣挂小钟，门内透更深处炉火。【近景】铁钳、坩埚、碎钟片、煤块、锁链、湿石地面上的铜屑。【中景】工作台、钟模、少量挂墙武器。【远景】石拱梁、铁链吊钩、烟道。" $KV/ref/style_B.jpg
gen S1_mirrordeep_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。镜渊城是倒挂在穹顶上的城市，塔尖朝下指向海面，不是立在地面上的城市。镜渊城全景，低机位平视。【主色调】冷青银为底，暖金灯火为点。【光源】主光=倒挂城自身灯窗的暖金下照；补光=镜面黑水反射的冷青光；关键点光=三座石质镜框的银光、小营地篝火。【雾】近处水面贴雾，中景青雾绕平台，远处穹顶下浓雾。【地标】穹顶倒挂的哥特钟楼城，塔尖朝下，倒挂铜钟悬在塔尖；镜面般静止的黑水与碎石平台，发光石板步道；三座立在水面上的巨大石质镜框，镜面映出另一处景象；中央倒钟广场摆一口倒扣大钟。【近景】湿石平台上苔藓、碎镜片、蜡烛、缆绳与小木栈。【中景】步道与镜框、篝火营地。【远景】倒挂城在水中的完整倒影。" $KV/ref/style_B.jpg
gen S2_coast_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。沉钟海岸，低机位沿岸视角。【主色调】幽绿灰海色，铜绿与暖黄灯点。【光源】主光=穹顶裂缝漏下的冷灰青光；补光=海面幽绿荧光；关键点光=码头暖黄灯笼、远处灯塔光束。【雾】近处浪沫水汽，中景低云般青雾，远处浓雾吞没海平线。【地标】退潮浅滩上半埋一口巨大铜绿古钟，钟口朝天积满海水。【近景】湿黑卵石与潮痕、藤壶、海藻、断锁链、碎钟片、半埋鲸骨。【中景】锈铁锚码头、木栈、缆绳。【远景】巨鲸骨礁与玄武岩柱、灯塔。" $KV/ref/style_B.jpg
gen S3_belltower_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。无声钟楼，低机位仰视3/4。【主色调】冷青铜为主，塔顶暗红与冷青交织。【光源】主光=顶层开放钟室里巨钟透出的暗红与冷青双色光；补光=海面冷青反光；关键点光=塔脚营地篝火、西侧铜梯通向的地下口橙色熔光。【雾】近处海雾贴水，中景淡雾绕塔身，远处穹顶下浓雾。空气中悬停着静止的雨滴。【地标】地底之海中央拔起的铜石混筑钟楼，塔身五段收分；塔门是两根立柱的门架挂一口裂开的铜钟。【近景】黑色湿礁、坠落的安魂钟、锈链、蜡烛。【中景】小营地、三根挂钟的石锚柱。【远景】穹顶岩壁垂下的铁链。没有天空，没有雪山。" $KV/ref/style_B.jpg
gen S4_abyss_v3 "暗岩深渊，竖井俯视。【主色调】自上而下沙金→冰蓝→熔红三段调色。【光源】主光=井底暗岩之魂的熔红裂纹光向上照；补光=中段冰晶的冷蓝反光；关键点光=各层石台火盆、台边发光石门。【雾】上层薄沙尘，中层冷雾，下层熔红热雾越往下越浓。【地标】一层层圆形石台向下螺旋；最底层平整圆形战斗石台上悬浮暗岩之魂（黑紫晶簇人形，布满熔红裂纹）；台边2到3道发光石门岔路。【近景】崩裂石阶边缘、锁链、碎晶、残烛。【中景】螺旋石台与栏柱。【远景】井底战斗台。" $KV/ref/style_B.jpg
gen D1_bronze_furnace_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。钟铜熔炉·浇铸台，略俯视。【主色调】橙金熔光为主，边缘冷青钟铜反光。【光源】主光=高处槽口浇下的熔铜瀑；补光=穹顶冷青反光；关键点光=沿地面沟槽流淌的熔铜、炉口。【雾】近处热浪火星，中景橙烟，远处浓黑青烟。【地标】直径约25米的平整圆形浇铸战斗台，中央是半铸成的巨钟钟模。【近景】冷却的铜渣、铁钳、碎钟片、锁链、被熔铜烤黑的湿石。【中景】四周站着未完成的铜铸傀儡，铜绿与新铜混杂。【远景】熔炉石墙、铁链吊钩。" $KV/ref/style_B.jpg
gen D2_choice_bell_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。钟楼顶层·抉择之钟，平视略仰。【主色调】左冷青右暗红，在钟腰交界。【光源】主光=巨钟自身左半冷青光、右半暗红熔光；补光=深渊下黑潮的幽光；关键点光=地面发红光的抉择印记。【雾】近处薄尘，中景青红两色雾分野，远处深渊浓雾。【地标】一口比教堂还大的巨钟悬在断裂穹顶下，钟下是一圈平整的圆形石台。【近景】碎钟片、断铁链、残烛、裂纹石面。【中景】圆形石台与垂向深渊的铁链。【远景】翻涌的黑色潮水。" $KV/ref/style_B.jpg
gen D3_domain_A_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。镜渊城是倒挂在穹顶上的城市，塔尖朝下指向海面，不是立在地面上的城市。钟楼领地（结局A），俯视3/4。【主色调】冷青底上暖金复苏，金色为主角。【光源】主光=穹顶裂缝洒下的金色光束；补光=镜面海冷青反光；关键点光=倒挂镜渊城一盏盏重新亮起的灯火、工坊火光、钟里少女轮廓的柔光。【雾】近处薄金雾，中景淡青雾，远处浓雾。【地标】镜面海平台上新建的铜顶建筑：中央三级尖顶钟楼挂旗、冒火光的铁匠工坊、堆满书卷的学会、停船码头、小圣堂、长街摊位、训练木桩场、档案馆。【近景】湿石街、灯笼、缆绳、木箱。【中景】半透明青色的回响居民身影。【远景】倒挂城倒影。" $KV/ref/style_B.jpg
gen D4_tidewhale_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。沉钟海岸深潮口，低机位海面视角。【主色调】黑青海色，金色钟声光。【光源】主光=鲸背三口古铜钟钟声激起的金色光环；补光=东岸灯塔光束；关键点光=雷云中的冷白闪电。【雾】近处浪沫水雾，中景低雾，远处浓雾与雷云。【地标】一头远古巨鲸从涨潮黑海中破出，背上藤壶间只嵌着三口大小不一的古铜钟（只有三口）；金色环形浪纹圈出约30米战斗水域。【近景】浪尖、漂浮碎木与缆绳、湿礁上的藤壶。【中景】环形浪纹。【远景】侧卧浅滩的巨钟、六棱玄武岩柱群、灯塔、穹顶岩壁。不要城市。" $KV/ref/style_B.jpg
gen D5_mirrorknights_v3 "地底之海世界观：头顶是岩石穹顶，没有天空。镜渊城是倒挂在穹顶上的城市，塔尖朝下指向海面，不是立在地面上的城市。镜渊城回响长街，街面低机位纵深透视。【主色调】冷青银为主，少量暖金街灯。【光源】主光=骑士碎镜甲裂缝透出的冷青光；补光=头顶倒挂铜钟与倒挂街屋的暖金灯；关键点光=积水中的倒影高光。【雾】近处贴地薄雾，中景青雾，远处浓雾吞没长街尽头。【地标】一队步行骑士列阵，没有马，盔甲明显由大小不一的碎镜片拼成，每片镜子映出不同角度；中央团长瑟兰更高大，持镜面大盾和长剑，披破旗；积水倒影里的骑士动作慢半拍。【近景】积水石板、碎镜片、残烛、锁链。【中景】骑士阵列。【远景】两侧倒挂的街屋与倒挂铜钟。" $KV/ref/style_B.jpg
gen B1_greystone_v4 "灰石营地，欧式暗黑奇幻，俯视3/4，黄昏。【主色调】灰蓝岩色，暖橙篝火。【光源】主光=西侧低斜的黄昏暖光；补光=山岩冷灰蓝天光；关键点光=中央篝火、北侧传送阵蓝光、营地火把。【雾】近处炊烟，中景淡雾绕围栏，远处山间浓雾。【地标】欧式中世纪木石瞭望塔（尖锥木瓦屋顶挂旗，绝对不要东方飞檐）；营地中心偏西一口石砌古井直径约3米，带木制辘轳架，井架挂小铜钟；北侧圆形石砌传送阵。【近景】泥泞车辙、木桶、柴堆、湿石、苔藓、尖桩围栏。【中景】帐篷、石墙、篝火。【远景】南侧石拱门通向绿色原野，东北山路，西南木栈道伸进雾沼，东边暗林。" $KV/ref/style_B.jpg
gen B2_darkrock_mine_v3 "暗岩山麓，欧式暗黑奇幻，平视。【主色调】冷灰紫岩色，幽紫晶光与暖黄灯笼对比。【光源】主光=阴天冷灰漫射光；补光=岩壁暗岩晶体的幽紫光；关键点光=矿洞口与远处矿工营地灯笼。【雾】近处矿尘，中景淡紫灰雾，远处山间浓雾。【地标】山脚废弃矿洞入口，木梁加固，矿车轨道深入黑暗。【近景】翻倒的矿车、碎矿石、锈镐、湿泥轨枕、苔藓。【中景】岩壁暗岩晶簇、木栈。【远景】矿工营地与山脊。" $KV/ref/style_B.jpg
gen B3_rotmarsh_v3 "腐沼湿地，欧式暗黑奇幻，低机位。【主色调】毒绿为主，暗褐泥色。【光源】主光=雾中散射的病态黄绿光；补光=水面荧光孢子；关键点光=神殿门口发光的腐化根须。【雾】近处贴水毒雾，中景绿雾，远处浓雾吞没枯林。【地标】半沉入泥水的古神殿。【近景】腐木、缠绕根须、泥水倒影、苔藓、破旧木栈与残烛。【中景】枯树林。【远景】神殿轮廓。" $KV/ref/style_B.jpg
gen B4_greenwind_v3 "翠风原野，欧式奇幻，晴天，俯视3/4。【主色调】翠绿与金黄麦色，暖调。【光源】主光=侧后方暖阳；补光=蓝天漫射；关键点光=远处星落遗迹祭坛的微光。【雾】远处山脚薄薄的大气透视蓝雾，近处无雾。【地标】高大风车塔、麦穗村4到5栋木石农舍、石拱桥。【近景】蜿蜒小河、湿润河石、野花、木篱、草丛。【中景】风吹麦浪、村庄。【远景】小山坡上一圈倒伏石柱围着发光祭坛；大块云影。" $KV/ref/style_B.jpg
gen B4b_starfall_v3 "星落高原，欧式奇幻，平视。【主色调】青草绿与星蓝。【光源】主光=傍晚暖斜光；补光=天空冷蓝；关键点光=残柱上星形碎晶的星蓝光。【雾】近处无雾，远处淡蓝雾。【地标】陨石坠落形成的环形遗迹，残柱镶着星形碎晶。【近景】碎晶散落、倒伏石块、苔藓、野草。【中景】环形残柱。【远景】高原丘陵与大块云影。" $KV/ref/style_B.jpg
gen B5_redsand_v3 "赤砂裂谷，平视。【主色调】赤红砂岩与金黄，阴影偏紫。【光源】主光=烈日斜光；补光=砂岩反射的暖红光；关键点光=王陵入口内的火盆。【雾】近处卷沙，中景热浪扭曲，远处浓沙雾。【地标】谷底巨大法老石像半埋沙中；两侧崖壁开凿王陵入口。【近景】风化石块、半埋陶罐、骨骸、沙纹。【中景】石像、残柱。【远景】峡谷尽头。" $KV/ref/style_B.jpg
gen B6_frostridge_v3 "霜脊高地，平视风雪。【主色调】冷白灰蓝，幽蓝魂灯为点。【光源】主光=灰白漫射天光；补光=冰面反光；关键点光=古墓大门两侧幽蓝魂灯。【雾】近处飞雪，中景风雪雾，远处浓白雪雾。【地标】冰湖下透出冰封的古墓穴大门；冰晶尖塔刺向灰白天空。【近景】冰裂纹、积雪、冻住的锁链与旗杆、冰下气泡。【中景】冰湖。【远景】冰晶尖塔与山脊。" $KV/ref/style_B.jpg
gen B7_emberwaste_v3 "烬落荒原，俯视3/4。【主色调】焦黑灰与熔红橙。【光源】主光=暗红天光；补光=地缝熔岩向上照；关键点光=铸造厂橙色炉口、火山口石门内熔光。【雾】近处余烬火星，中景灰烟，远处浓黑烟。【地标】正中远景火山口被凿成巨大王座形石门，门内熔光（熔心王座），不是城堡；左远景高烟囱林立、仍在运转的铸造厂。【近景】焦土裂缝熔岩网、碎岩、烧焦木桩、锈链。【中景】右侧一角石墙与旗帜的据点。【远景】王座石门。" $KV/ref/style_B.jpg
